using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Collections.Generic;
class MakeIcon {
 static Bitmap Draw(int size){var b=new Bitmap(size,size,PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(size/64f,size/64f);Color outline=ColorTranslator.FromHtml("#104c80");using(var p=new Pen(outline,7)){g.DrawArc(p,38,19,20,21,-90,180);g.DrawLine(p,43,19,48,19);g.DrawLine(p,43,40,48,40);}using(var path=new GraphicsPath()){path.AddLine(9,13,46,13);path.AddLine(46,13,46,40);path.AddBezier(46,40,46,53,9,53,9,40);path.CloseFigure();using(var fill=new SolidBrush(ColorTranslator.FromHtml("#168bd2")))g.FillPath(fill,path);using(var p=new Pen(outline,3))g.DrawPath(p,path);}using(var fill=new SolidBrush(ColorTranslator.FromHtml("#8edcff")))g.FillEllipse(fill,9,8,37,10);using(var p=new Pen(outline,3))g.DrawEllipse(p,9,8,37,10);using(var p=new Pen(ColorTranslator.FromHtml("#70cdff"),3)){p.StartCap=p.EndCap=LineCap.Round;g.DrawLine(p,14,23,14,38);}if(size>=32)using(var f=new Font("Arial",11,FontStyle.Bold,GraphicsUnit.Pixel))g.DrawString("ABC",f,Brushes.White,18,24);var points=new[]{new PointF(28,48),new PointF(37,57),new PointF(59,32)};foreach(var width in new[]{11,7})using(var p=new Pen(width==11?Color.White:ColorTranslator.FromHtml("#219c55"),width)){p.StartCap=p.EndCap=LineCap.Round;p.LineJoin=LineJoin.Round;g.DrawLines(p,points);}}return b;}
 static void Main(string[] args){string root=args[0];int[] sizes={16,20,24,32,48,64,128,256};var data=new List<byte[]>();foreach(int size in sizes)using(var b=Draw(size)){using(var ms=new MemoryStream()){b.Save(ms,ImageFormat.Png);data.Add(ms.ToArray());}if(size==256)b.Save(Path.Combine(root,"spellchecker.png"),ImageFormat.Png);}using(var w=new BinaryWriter(File.Create(Path.Combine(root,"spellchecker.ico")))){w.Write((ushort)0);w.Write((ushort)1);w.Write((ushort)sizes.Length);int offset=6+sizes.Length*16;for(int i=0;i<sizes.Length;i++){w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)0);w.Write((byte)0);w.Write((ushort)1);w.Write((ushort)32);w.Write(data[i].Length);w.Write(offset);offset+=data[i].Length;}foreach(var bytes in data)w.Write(bytes);}}
}

